[patterns/application/micro-frontend/PTN-APP-MFE-010-event-bus-communication-pattern.md#variation-2-event-bus-with-priority-subscribers]

#### Variation 2: Event Bus with Priority Subscribers

**Use Case**: Some subscribers must execute before others (e.g., audit logging before business logic).

**Implementation:**

```typescript
export class EventBusWithPriority extends EventBus {
  private priorityHandlers = new Map<string, Array<{ handler: EventHandler; priority: number }>>();

  subscribe<T>(eventType: string, handler: EventHandler<T>, priority = 0): () => void {
    if (!this.priorityHandlers.has(eventType)) {
      this.priorityHandlers.set(eventType, []);
    }

    const handlers = this.priorityHandlers.get(eventType)!;
    handlers.push({ handler, priority });

    // Sort by priority (higher priority first)
    handlers.sort((a, b) => b.priority - a.priority);

    return () => {
      const idx = handlers.findIndex(h => h.handler === handler);
      if (idx !== -1) handlers.splice(idx, 1);
    };
  }

  protected invokeHandlers(eventType: string, data: any): void {
    const handlers = this.priorityHandlers.get(eventType) || [];

    // Invoke in priority order (but still async)
    handlers.forEach(({ handler }) => {
      try {
        Promise.resolve(handler(data)).catch(error => {
          this.handleSubscriberError(error, eventType, data);
        });
      } catch (error) {
        this.handleSubscriberError(error, eventType, data);
      }
    });
  }
}

// Usage:
eventBus.subscribe('claim.submitted', auditHandler, 10);  // High priority
eventBus.subscribe('claim.submitted', businessHandler, 0);  // Normal priority
```

**Trade-offs:**
- ✅ Ensures critical subscribers (audit logging) execute first
- ✅ Useful for compliance requirements (log before processing)
- ❌ More complex implementation
- ❌ Still asynchronous (no blocking guarantees)

