#### Step 1: Implement Event Bus in Shell

```typescript
// shell/src/services/EventBus.ts
import { z } from 'zod';

export type EventHandler<T = any> = (data: T) => void | Promise<void>;

export class EventBus {
  private handlers = new Map<string, Set<EventHandler>>();
  private eventLog: Array<{ type: string; data: any; timestamp: Date }> = [];

  /**
   * Publish event with schema validation
   */
  publish<T>(eventType: string, data: T, schema: z.ZodSchema<T>): void {
    const startTime = performance.now();

    try {
      // Validate event payload
      const validatedData = schema.parse(data);

      // Log event for observability
      this.logEvent(eventType, validatedData);

      // Get subscribers
      const subscribers = this.handlers.get(eventType);

      if (!subscribers || subscribers.size === 0) {
        console.debug(`[EventBus] No subscribers for event: ${eventType}`);
        return;
      }

      // Invoke all subscribers
      console.log(`[EventBus] Publishing ${eventType} to ${subscribers.size} subscriber(s)`);

      subscribers.forEach(async (handler) => {
        try {
          await handler(validatedData);
        } catch (error) {
          // Subscriber errors don't affect publisher (fire-and-forget)
          console.error(`[EventBus] Subscriber error for ${eventType}:`, error);

          // Report to error tracking
          this.reportSubscriberError(eventType, error);
        }
      });

      const duration = performance.now() - startTime;
      console.debug(`[EventBus] Published ${eventType} in ${duration.toFixed(2)}ms`);
    } catch (error) {
      // Schema validation error - publisher should handle
      console.error(`[EventBus] Schema validation failed for ${eventType}:`, error);
      throw new Error(`Invalid event payload for ${eventType}: ${error.message}`);
    }
  }

  /**
   * Subscribe to event type
   * Returns unsubscribe function
   */
  subscribe<T>(eventType: string, handler: EventHandler<T>): () => void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, new Set());
    }

    this.handlers.get(eventType)!.add(handler);

    console.log(`[EventBus] Subscribed to ${eventType} (${this.handlers.get(eventType)!.size} subscriber(s))`);

    // Return unsubscribe function
    return () => {
      const subscribers = this.handlers.get(eventType);
      if (subscribers) {
        subscribers.delete(handler);
        console.log(`[EventBus] Unsubscribed from ${eventType} (${subscribers.size} remaining)`);

        // Cleanup empty sets
        if (subscribers.size === 0) {
          this.handlers.delete(eventType);
        }
      }
    };
  }

  /**
   * Get event history (for debugging)
   */
  getEventLog(): Array<{ type: string; data: any; timestamp: Date }> {
    return [...this.eventLog];
  }

  /**
   * Clear event log (for testing)
   */
  clearEventLog(): void {
    this.eventLog = [];
  }

  private logEvent(eventType: string, data: any): void {
    this.eventLog.push({
      type: eventType,
      data,
      timestamp: new Date(),
    });

    // Keep only last 100 events to prevent memory leak
    if (this.eventLog.length > 100) {
      this.eventLog.shift();
    }

    // Send to observability platform (DataDog, CloudWatch)
    if (window.datadog) {
      window.datadog.logger.info(`Event: ${eventType}`, {
        eventType,
        eventData: JSON.stringify(data),
      });
    }
  }

  private reportSubscriberError(eventType: string, error: any): void {
    // Send to error tracking (Sentry, DataDog)
    if (window.Sentry) {
      window.Sentry.captureException(error, {
        tags: {
          eventType,
          component: 'EventBus',
        },
      });
    }
  }
}
```

**Provide Event Bus to Modules:**

