#### Step 2: Define Event Schemas

Create shared event schemas package:

```typescript
// packages/mfe-events/src/claimEvents.ts
import { z } from 'zod';

/**

 * Claim Submitted Event
 * Published by: Claims MFE
 * Subscribers: Care Coordination, Fraud Detection, Analytics
 */
export const ClaimSubmittedEventSchema = z.object({
  claimId: z.string().uuid(),
  claimNumber: z.string(),
  memberId: z.string().uuid(),
  providerId: z.string().uuid(),
  serviceDate: z.string().date(),
  totalAmount: z.number().positive(),
  diagnosis: z.array(z.string()).min(1),  // ICD-10 codes
  procedures: z.array(z.string()).min(1),  // CPT codes
  submittedAt: z.string().datetime(),
  submittedBy: z.string(),  // User ID
});

export type ClaimSubmittedEvent = z.infer<typeof ClaimSubmittedEventSchema>;

/**

 * Claim Approved Event
 * Published by: Claims MFE
 * Subscribers: Payment, Notifications, Analytics
 */
export const ClaimApprovedEventSchema = z.object({
  claimId: z.string().uuid(),
  approvedAmount: z.number().positive(),
  approvedAt: z.string().datetime(),
  approvedBy: z.string(),
});

export type ClaimApprovedEvent = z.infer<typeof ClaimApprovedEventSchema>;

/**

 * Claim Denied Event
 * Published by: Claims MFE
 * Subscribers: Notifications, Appeals, Analytics
 */
export const ClaimDeniedEventSchema = z.object({
  claimId: z.string().uuid(),
  denialReason: z.string(),
  denialCode: z.string(),
  deniedAt: z.string().datetime(),
});

export type ClaimDeniedEvent = z.infer<typeof ClaimDeniedEventSchema>;
```

