[patterns/application/micro-frontend/PTN-APP-MFE-010-event-bus-communication-pattern.md#step-3-publish-events-from-module]

#### Step 3: Publish Events from Module

```typescript
// claims-mfe/src/services/claimService.ts
import { MfeContext } from '@gainwell/mfe-types';
import { ClaimSubmittedEventSchema, ClaimSubmittedEvent } from '@gainwell/mfe-events';

export class ClaimService {
  constructor(private context: MfeContext) {}

  async submitClaim(claimData: ClaimFormData): Promise<Claim> {
    try {
      // Submit claim to backend
      const response = await fetch(`${this.context.config.apiBaseUrl}/claims`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(claimData),
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error(`Claim submission failed: ${response.statusText}`);
      }

      const claim = await response.json();

      // Publish domain event for other modules
      const event: ClaimSubmittedEvent = {
        claimId: claim.id,
        claimNumber: claim.claimNumber,
        memberId: claim.memberId,
        providerId: claim.providerId,
        serviceDate: claim.serviceDate,
        totalAmount: claim.totalAmount,
        diagnosis: claim.diagnosisCodes,
        procedures: claim.procedureCodes,
        submittedAt: new Date().toISOString(),
        submittedBy: this.context.user.id,
      };

      try {
        this.context.events.publish(
          'claim.submitted',
          event,
          ClaimSubmittedEventSchema
        );
      } catch (error) {
        // Event publication error doesn't fail claim submission
        console.error('[ClaimService] Failed to publish event:', error);
        // Report to error tracking but proceed
      }

      return claim;
    } catch (error) {
      console.error('[ClaimService] Claim submission failed:', error);
      throw error;
    }
  }
}
```

**Usage in Component:**

```typescript
