[patterns/application/micro-frontend/PTN-APP-MFE-010-event-bus-communication-pattern.md#step-4-subscribe-to-events-in-module]

#### Step 4: Subscribe to Events in Module

```typescript
// carecoord-mfe/src/hooks/useClaimEvents.ts
import { useEffect } from 'react';
import { MfeContext } from '@gainwell/mfe-types';
import { ClaimSubmittedEvent } from '@gainwell/mfe-events';
import { caregapService } from '../services/caregapService';

export function useClaimEvents(context: MfeContext) {
  useEffect(() => {
    console.log('[CareCoord] Subscribing to claim events');

    // Subscribe to claim.submitted events
    const unsubscribe = context.events.subscribe<ClaimSubmittedEvent>(
      'claim.submitted',
      async (event) => {
        console.log('[CareCoord] Received claim.submitted event:', event);

        try {
          // Trigger care gap analysis asynchronously
          await caregapService.analyzeCaregaps(event.memberId, {
            claimId: event.claimId,
            diagnosisCodes: event.diagnosis,
            serviceDate: event.serviceDate,
          });

          console.log(`[CareCoord] Care gap analysis completed for member ${event.memberId}`);
        } catch (error) {
          console.error('[CareCoord] Care gap analysis failed:', error);
          // Error logged; doesn't affect Claims MFE
        }
      }
    );

    // Cleanup subscription on unmount
    return () => {
      console.log('[CareCoord] Unsubscribing from claim events');
      unsubscribe();
    };
  }, [context.events]);
}
```

**Usage in App:**

```typescript
