[patterns/application/micro-frontend/PTN-APP-MFE-010-event-bus-communication-pattern.md#security-implementation-for-event-bus]

#### Security Implementation for Event Bus

**Security Risk Assessment:**

| Risk | Severity | Mitigation |
|------|----------|------------|
| XSS via malicious event payloads | **Critical** | DOMPurify sanitization, schema validation |
| Injection attacks via unvalidated payloads | **High** | Zod schema validation with strict types |
| Malicious modules publishing crafted events | **High** | Event allowlist, schema validation |
| Subscriber DoS (infinite loop, memory leak) | Medium | Rate limiting, execution timeouts |
| Event log PHI exposure | **High** | Sanitized logging, no PHI in events |

**1. Event Bus Security Implementation:**

```typescript
// shell/src/events/SecureEventBus.ts
import { z } from 'zod';
import DOMPurify from 'dompurify';
import Sentry from '@sentry/react';

interface EventSchema {
  shape: z.ZodObject<any>;
  allowedPublishers?: string[]; // Optional: restrict publishers
}

class SecureEventBus {
  private eventEmitter = new EventEmitter();
  private allowedEvents: Map<string, EventSchema> = new Map();
  private rateLimiter = new RateLimiter();
  private auditLogger = new AuditLogger();

  registerEvent<T extends z.ZodObject<any>>(
    eventType: string,
    schema: T,
    allowedPublishers?: string[]
  ) {
    this.allowedEvents.set(eventType, { shape: schema, allowedPublishers });
  }

  publish<T>(
    eventType: string,
    payload: T,
    publisherModuleId: string
  ): void {
    // 1. Check rate limit (prevent DoS)
    if (!this.rateLimiter.checkRateLimit(publisherModuleId, eventType)) {
      throw new SecurityError(
        `Rate limit exceeded for module ${publisherModuleId} ` +
        `publishing ${eventType}`
      );
    }

    // 2. Validate event is registered (allowlist)
    const eventSchema = this.allowedEvents.get(eventType);
    if (!eventSchema) {
      throw new SecurityError(
        `Event type '${eventType}' not registered in allowed events. ` +
        `Register event with eventBus.registerEvent() before publishing.`
      );
    }

    // 3. Verify publisher is allowed (optional)
    if (eventSchema.allowedPublishers &&
        !eventSchema.allowedPublishers.includes(publisherModuleId)) {
      throw new SecurityError(
        `Module ${publisherModuleId} not authorized to publish ${eventType}`
      );
    }

    // 4. Validate payload against schema
    let validatedPayload: T;
    try {
      validatedPayload = eventSchema.shape.parse(payload);
    } catch (error) {
      if (error instanceof z.ZodError) {
        Sentry.captureException(error, {
          tags: { type: 'event_validation_failure', eventType },
          extra: { errors: error.errors, payload }
        });
        throw new SecurityError(
          `Payload validation failed for ${eventType}: ${error.message}`
        );
      }
      throw error;
    }

    // 5. Sanitize string values (prevent XSS)
    const sanitizedPayload = this.sanitizePayload(validatedPayload);

    // 6. Audit log event (sanitized payload only)
    this.auditLogger.logEvent({
      eventType,
      publisherModuleId,
      timestamp: new Date().toISOString(),
      payloadSummary: this.createPayloadSummary(sanitizedPayload)
    });

    // 7. Publish to subscribers
    const subscribers = this.eventEmitter.listeners(eventType);
    subscribers.forEach(subscriber => {
      try {
        // Execute subscriber with timeout
        Promise.race([
          Promise.resolve(subscriber(sanitizedPayload)),
          this.timeoutPromise(5000) // 5s timeout
        ]).catch(error => {
          // Log subscriber error but don't propagate to publisher
          Sentry.captureException(error, {
            tags: { type: 'subscriber_error', eventType },
            extra: { subscriberName: subscriber.name }
          });
        });
      } catch (error) {
        // Synchronous subscriber errors don't affect other subscribers
        console.error(`Subscriber error for ${eventType}:`, error);
      }
    });
  }

  private sanitizePayload(payload: unknown): unknown {
    if (typeof payload === 'string') {
      return DOMPurify.sanitize(payload, {
        ALLOWED_TAGS: [],      // No HTML tags
        ALLOWED_ATTR: [],      // No attributes
        KEEP_CONTENT: true     // Keep text only
      });
    }

    if (Array.isArray(payload)) {
      return payload.map(item => this.sanitizePayload(item));
    }

    if (typeof payload === 'object' && payload !== null) {
      const sanitized: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(payload)) {
        sanitized[key] = this.sanitizePayload(value);
      }
      return sanitized;
    }

    return payload; // numbers, booleans, null pass through
  }

  private createPayloadSummary(payload: unknown): string {
    // Create summary without including full payload (prevent log PHI exposure)
    if (typeof payload === 'object' && payload !== null) {
      const keys = Object.keys(payload);
      return `{ ${keys.join(', ')} }`; // Only log field names, not values
    }
    return typeof payload;
  }

  private timeoutPromise(ms: number): Promise<never> {
    return new Promise((_, reject) =>
      setTimeout(() => reject(new Error('Subscriber timeout')), ms)
    );
  }
}
```

**2. Rate Limiting Implementation:**

```typescript
// shell/src/events/RateLimiter.ts
class RateLimiter {
  private eventCounts: Map<string, number[]> = new Map();
  private readonly MAX_EVENTS_PER_MINUTE = 100;

  checkRateLimit(moduleId: string, eventType: string): boolean {
    const key = `${moduleId}:${eventType}`;
    const now = Date.now();
    const oneMinuteAgo = now - 60000;

    // Get recent events for this module/event combination
    let timestamps = this.eventCounts.get(key) || [];

    // Remove events older than 1 minute (sliding window)
    timestamps = timestamps.filter(ts => ts > oneMinuteAgo);

    // Check if limit exceeded
    if (timestamps.length >= this.MAX_EVENTS_PER_MINUTE) {
      console.error(
        `Rate limit exceeded: ${moduleId} published ${eventType} ` +
        `${timestamps.length} times in last minute (max: ${this.MAX_EVENTS_PER_MINUTE})`
      );
      return false;
    }

    // Add current event
    timestamps.push(now);
    this.eventCounts.set(key, timestamps);

    return true;
  }
}
```

**3. Secure Event Registration:**

```typescript
// shell/src/App.tsx
import { SecureEventBus } from './events/SecureEventBus';
import {
  ClaimSubmittedEventSchema,
  MemberSelectedEventSchema,
  ProviderCredentialedEventSchema
} from '@gainwell/event-bus/schemas';

function initializeEventBus(): SecureEventBus {
  const eventBus = new SecureEventBus();

  // Register allowed events with schemas
  eventBus.registerEvent(
    'claim.submitted',
    ClaimSubmittedEventSchema,
    ['claims-mfe'] // Only Claims MFE can publish
  );

  eventBus.registerEvent(
    'member.selected',
    MemberSelectedEventSchema
    // Any module can publish (no allowedPublishers)
  );

  eventBus.registerEvent(
    'provider.credentialed',
    ProviderCredentialedEventSchema,
    ['provider-mfe'] // Only Provider MFE can publish
  );

  return eventBus;
}
```

**4. Secure Subscriber Implementation:**

```typescript
// care-coordination-mfe/src/hooks/useClaimEvents.ts
import { useEffect } from 'react';
import { useEventBus } from '@gainwell/mfe-context';
import { ClaimSubmittedEvent } from '@gainwell/event-bus/types';

export function useClaimEvents() {
  const eventBus = useEventBus();

  useEffect(() => {
    const handleClaimSubmitted = async (event: ClaimSubmittedEvent) => {
      try {
        // 1. Verify user has permission to process this event
        if (!hasPermission('care_gap_analysis')) {
          console.warn('User lacks permission for care gap analysis');
          return;
        }

        // 2. Fetch PHI from backend (not from event)
        const memberDetails = await fetchMemberDetails(event.memberId);

        // 3. Process event with PHI from backend
        await triggerCareGapAnalysis({
          claimId: event.claimId,
          memberDetails, // PHI fetched securely
        });

      } catch (error) {
        // Log error but don't throw (prevents affecting other subscribers)
        console.error('Error processing claim.submitted event:', error);
        Sentry.captureException(error, {
          tags: { eventType: 'claim.submitted' },
          extra: { claimId: event.claimId }
        });
      }
    };

    // Subscribe to event
    const unsubscribe = eventBus.subscribe('claim.submitted', handleClaimSubmitted);

    // Cleanup on unmount
    return unsubscribe;
  }, [eventBus]);
}
```

